import json
import os
from datetime import datetime, timezone

HISTORY_FILE = os.path.join(os.path.expanduser("~"), ".basic_calculator_history.jsonl")


@tool
def basic_calculator(query):
    try:
        result = eval(query)
        # Record the calculation in a local history file
        entry = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "query": query,
            "result": str(result),
        }
        with open(HISTORY_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry) + "\n")
        return f'The result is {result}'
    except (SyntaxError, NameError) as e:
        return f"Sorry, I couldn't calculate that due to an error: {e}"
